const leftInitialPath =
  'M51.5789 0.0602923C56.1164 -0.0601898 60.8759 -0.0890503 65.3367 0.855785C66.6206 1.15678 67.7892 1.53652 68.8898 2.2747C71.8625 4.26931 71.1433 8.23782 67.4087 8.57726C65.9267 8.71188 64.5207 8.50637 63.03 8.44334C61.0129 8.37443 58.994 8.36371 56.976 8.41117C49.1356 8.62655 41.7688 9.52201 34.0589 10.7955C34.5834 11.5236 35.0372 12.4978 34.7521 13.3844C34.0036 15.7123 32.6551 18.1713 31.6827 20.4577C28.8949 27.0122 26.2452 34.0793 25.3846 41.167C25.3183 42.6975 25.0765 45.3064 25.7433 46.7149C26.4898 48.2917 27.5157 49.5573 26.0862 51.2439C23.9892 53.7182 19.366 53.1164 17.0647 51.2054C15.0433 49.5269 14.3586 47.2401 14.1042 44.7308C13.5339 35.3558 19.6196 21.6729 23.8772 13.326C21.0762 14.0244 17.9554 15.0581 15.266 16.0681C14.1697 16.4756 13.0828 16.9078 12.0064 17.3639C10.1048 18.1774 8.1783 19.2306 6.07571 19.3597C4.47906 19.4577 2.76912 19.0587 1.55379 17.9844C0.622366 17.1611 0.0783666 15.9508 0.0078466 14.7229C-0.0731466 13.3118 0.478097 11.9965 1.41947 10.9529C6.17075 5.68595 30.4434 2.10859 37.817 1.22152C42.389 0.67338 46.9792 0.286057 51.5789 0.0602923Z';

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

export const LogoWrite = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();

  const writeProgress = interpolate(frame, [0.15 * fps, 3.45 * fps], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });

  const settle = interpolate(frame, [3.25 * fps, 3.9 * fps], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.bezier(0.2, 0, 0, 1),
  });

  const revealWidth = LOGO_WIDTH * writeProgress;
  const edgeWidth = interpolate(writeProgress, [0, 0.18, 1], [5, 12, 4], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const markerX = clamp(revealWidth, 0, LOGO_WIDTH);
  const markerOpacity = interpolate(
    frame,
    [0, 0.15 * fps, 3.45 * fps, 3.8 * fps],
    [0, 1, 1, 0],
    {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'},
  );

  const logoScale = interpolate(frame, [0, 3.9 * fps], [0.985, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });

  return (
    <AbsoluteFill
      style={{
        alignItems: 'center',
        background:
          'linear-gradient(135deg, #fffaf5 0%, #ffffff 54%, #f1fbf7 100%)',
        display: 'flex',
        justifyContent: 'center',
      }}
    >
      <svg
        aria-label="Woszkowski logo writing animation"
        role="img"
        viewBox="-8 -10 158 73"
        style={{
          filter: 'drop-shadow(0 18px 36px rgba(255, 142, 44, 0.16))',
          maxWidth: 1280,
          overflow: 'visible',
          transform: `scale(${logoScale})`,
          width: '66%',
        }}
      >
        <defs>
          <linearGradient
            id="write-edge"
            x1={Math.max(0, markerX - edgeWidth)}
            x2={markerX + edgeWidth}
            y1="0"
            y2="0"
            gradientUnits="userSpaceOnUse"
          >
            <stop offset="0%" stopColor="white" />
            <stop offset="72%" stopColor="white" />
            <stop offset="100%" stopColor="black" />
          </linearGradient>
          <mask id="write-mask" maskUnits="userSpaceOnUse">
            <rect
              x="-8"
              y="-10"
              width={Math.max(0, revealWidth - edgeWidth + 8)}
              height="73"
              fill="white"
            />
            <rect
              x={Math.max(-8, revealWidth - edgeWidth)}
              y="-10"
              width={edgeWidth * 2}
              height="73"
              fill="url(#write-edge)"
            />
          </mask>
          <radialGradient id="ink-tip" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#FFD2A3" stopOpacity="1" />
            <stop offset="58%" stopColor={ORANGE} stopOpacity="0.42" />
            <stop offset="100%" stopColor={ORANGE} stopOpacity="0" />
          </radialGradient>
        </defs>

        <g opacity={settle * 0.08}>
          <path d={leftInitialPath} fill={ORANGE} />
          <path d={rightWordPath} fill={ORANGE} />
        </g>

        <g mask="url(#write-mask)">
          <path d={leftInitialPath} fill={ORANGE} />
          <path d={rightWordPath} fill={ORANGE} />
        </g>

        <g
          opacity={markerOpacity}
          transform={`translate(${markerX - 3.8} 27) rotate(-12)`}
        >
          <ellipse cx="0" cy="0" rx="10" ry="18" fill="url(#ink-tip)" />
          <ellipse cx="0" cy="0" rx="2.4" ry="7.2" fill={ORANGE} />
        </g>
      </svg>
    </AbsoluteFill>
  );
};
